from __future__ import annotations

import argparse
import hashlib
import json
import re
import struct
import sys
import unicodedata
from datetime import datetime
from pathlib import Path

DIMENSIONS = ("content_form", "hierarchy", "typography", "space", "image_material", "emotion_control", "ai_slop")
