def digest(path):
    h = hashlib.sha256()
    with open(path, "rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def resolve(path, base):
    if not isinstance(path, str) or not path:
        raise ValueError("missing explicit path")
    result = Path(path)
    return (base / result if not result.is_absolute() else result).resolve(strict=True)


def read_json(path):
    raw = Path(path).read_bytes()
    return json.loads(raw), {"path": str(Path(path).resolve(strict=True)), "sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw)}


def pin(value, base, errors, label):
    try:
        if not isinstance(value, dict) or not re.fullmatch(r"[0-9a-f]{64}", str(value.get("sha256", ""))):
            raise ValueError("missing lowercase SHA-256 pin")
        path = resolve(value.get("path"), base)
        if not path.is_file():
            raise ValueError("not a file")
        actual = digest(path)
        if actual != value["sha256"]:
            raise ValueError("bytes disagree with pinned SHA-256")
        return {"path": str(path), "sha256": actual, "bytes": path.stat().st_size}
    except (ValueError, OSError) as exc:
        errors.append(f"{label}: {exc}")
        return None


def text(value):
    return isinstance(value, str) and bool(value.strip())


def integer(value, low=1, high=5):
    return type(value) is int and low <= value <= high


def fresh_exec_argv(argv):
    """Recognize the runner's actual global flags before its sole exec command."""
    if not isinstance(argv, list) or len(argv) < 3 or any(not isinstance(x, str) for x in argv) or Path(argv[0]).name not in ("codex", "codex.exe"):
        return False
    index, seen = 1, set()
    while index < len(argv) and argv[index] != "exec":
        flag = argv[index]
        if flag == "--no-daemon" and flag not in seen:
            seen.add(flag)
            index += 1
        elif flag == "--ask-for-approval" and flag not in seen and index + 1 < len(argv) and argv[index + 1] == "never":
