def ratio_correct(width, height, ratio, policy="exact", pixel_dimensions=None):
    """Exact by default; an explicit R7 policy permits <=half a pixel on one edge."""
    a, b = ratio
    difference = abs(width * b - height * a)
    if pixel_dimensions is not None:
        return [width, height] == pixel_dimensions and difference == 0
    return difference == 0 or (policy == "nearest-integer-single-edge" and
